    'course.process.column': 'tusen',
    'course.viz.chart': 'Folketall per län 2024',
    'course.welcome.title': 'Velkommen til Dataspatium',
    'course.welcome.p1': 'Dataspatium henter, bearbeider, analyserer, visualiserer og eksporterer data helt i nettleseren. Ingenting installeres, og dataene dine forlater ikke datamaskinen med mindre du selv henter fra et API.',
    'course.welcome.p2': 'Grunnkurset tar omtrent ti minutter. Du følger et konkret eksempel, {example}, gjennom appens åtte moduser: {modes}. I hvert trinn kan du gjøre oppgaven selv eller la kurset gjøre den for deg.',
    'course.welcome.p3': 'Skjermen ser lik ut i alle moduser: modusene øverst, objektpanelet til venstre, arbeidsflaten i midten, egenskapene til høyre og loggen nederst. Kurset kan minimeres og åpnes igjen fra hjelpen.',
    'course.import.title': 'Hent: hent data',
    'course.import.p1': 'Alle data i appen ligger i datasett: tabeller med navngitte kolonner, der hver kolonne har en type som tekst, heltall, tall eller dato. Data kan hentes fra filer (CSV, Excel, JSON, Parquet, SPSS med flere), innlimt tekst, nettadresser og åpne API-er fra etater i hele Norden.',
    'course.import.task': 'Gå til {mode} og klikk på {button}. Da opprettes datasettet {name}.',
    'course.import.done': 'Datasettet er opprettet: 290 svenske kommuner med kolonnene kommunkod (kommunekode), kommun (kommune), lanskod (länskode), lan (län), ar (år) og folkmangd (folketall). Kortnavnet er {short}.',
    'course.manage.title': 'Håndter: datasett og arbeidsområdet',
    'course.manage.p1': 'Hvert datasett har et navn og et kortnavn. Kortnavnet, her {short}, har bare små bokstaver, sifre og understreker og brukes i SQL og R. I {mode} ser du kilden, størrelsen, kolonnene med typer og beskrivelser og versjoner som du kan gå tilbake til.',
    'course.manage.p2': 'Alt lagres automatisk i nettleseren. Ta en sikkerhetskopi av arbeidsområdet av og til med {backup}, slik at ingenting går tapt hvis nettleserens data blir slettet.',
    'course.manage.task': 'Åpne {mode}, velg datasettet i objektpanelet og se på opplysningene og kolonnene.',
    'course.manage.done': 'Her kan du også endre navn og kortnavn, dele datasett som pakker og slette dem.',
    'course.process.title': 'Bearbeid: rens og beregn',
    'course.process.p1': 'I {mode} ser du hele tabellen. Klikk på en kolonneoverskrift for å sortere og se kolonnens profil med manglende verdier, unike verdier og fordeling. Rett verdier direkte i cellene eller med handlinger.',
    'course.process.p2': 'Hver endring blir et trinn i datasettets {recipe}. Trinnene kan angres, kjøres på nytt på en ny versjon av dataene og kopieres som R- eller SQL-kode.',
    'course.process.task': 'Lag en kolonne med folketallet i tusen: {mode} → {actions} → {group} → {op}. Angi navnet {column} og uttrykket {expression}.',
    'course.process.done': 'Kolonnen {column} ligger nå sist i tabellen, og trinnet står i oppskriften.',
    'course.sql.title': 'Analyser: spør med SQL',
    'course.sql.p1': '{mode} er modusen for kode og statistikk. I SQL-fanen heter det valgte datasettet {data}, men alle datasett kan også nås med kortnavnene sine. Derfor kan én spørring koble sammen flere datasett.',
    'course.sql.task': 'Åpne {mode} → {tab}, skriv spørringen nedenfor og klikk på {run}. Spørringen summerer folketallet per län.',
    'course.sql.done': 'Stockholms län er størst med nesten 2,5 millioner innbyggere, fulgt av Västra Götalands og Skåne län. Med {save} blir resultatet et nytt datasett.',
    'course.r.title': 'Analyser: regn med R',
    'course.r.p1': 'R-fanen kjører R direkte i nettleseren med pakker som dplyr og ggplot2. {read} leser et datasett som en data frame, og {write} lagrer en data frame som et nytt datasett. Første gang tar det noen sekunder å starte R.',
    'course.r.task': 'Åpne {mode} → {tab}, skriv koden nedenfor og klikk på {run}. Koden oppsummerer folketallet og tegner et histogram.',
    'course.r.done': 'Medianen er drøyt 16 000 innbyggere: halvparten av kommunene er mindre enn det, og den største, Stockholm, har nesten en million. Derfor har diagrammet en logaritmisk skala.',
    'course.viz.title': 'Visualiser: lag et diagram',
    'course.viz.p1': 'Diagrammer lages med diagrambyggeren (Vega-Lite), ferdige D3-maler eller R. Alle bruker appens farger og skrifttyper, tegnes på nytt når dataene endres, og kan samles i dashbord med felles filtre.',
    'course.viz.task': 'Åpne {mode} → {new} → {builder}. Velg {type}, sett {x} til lan ({y} er allerede folkmangd) og klikk på {save}.',
    'course.viz.done': 'Diagrammet er lagret. Prøv også diagramtypen {map} sammen med eksempeldatasettet {boundaries} for å vise folketallet på et kart.',
    'course.export.title': 'Eksporter: del resultatet',
    'course.export.p1': 'I {mode} lagrer du data som CSV, Excel, JSON, Parquet, SQLite, SPSS og flere formater, diagrammer som PNG, SVG, PDF eller PowerPoint og dokumenter fra maler som Word, PDF, HTML eller LaTeX, også ett dokument per gruppe i én kjøring.',
    'course.export.task': 'Åpne {mode}, velg for eksempel formatet Excel og klikk på {run}.',
    'course.export.done': 'Filen havner blant nettleserens nedlastinger. Fanene {charts} og {documents} fungerer på samme måte for diagrammer og dokumenter.',
    'course.finish.title': 'Ferdig: slik går du videre',
    'course.finish.p1': 'Du har gått gjennom hele kjeden: hente, håndtere, bearbeide, analysere, visualisere og eksportere.',
    'course.finish.p2': 'Fortsett med egne data: slipp en fil i {import}, velg land og hent fra et åpent API, skriv notatbøker med tekst, R og SQL i {analyse} eller lag dokumentmaler i {export}. Alt+1–6 bytter modus, og {palette} åpner kommandopaletten.',
    'course.finish.p3': 'Kurset er fortsatt tilgjengelig under {help} og i kommandopaletten.',
    'floating.collapse': 'Minimer',
